package dashboard

import (
	"fmt"
	"net/http"
	"path/filepath"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// Graph status values CatalogEntry.GraphStatus takes.
const (
	graphMatched       = "matched"
	graphNoTopology    = "no-topology"
	graphNotInGraph    = "not-in-graph"
	graphTopologyError = "topology-error"
	graphPending       = "pending"
)

// Check severity values.
const (
	severityWarn = "warn"
	severityInfo = "info"
)

// CatalogEntry is the /api/catalog/{path} payload: the integration's header
// facts and its checks, assembled from the cached topology report and the
// scaffold walk. Deployment state is NOT embedded — it stays on
// /api/deploy/{path}, which costs a GitOps checkout refresh.
type CatalogEntry struct {
	// Component is the header identity: the graph's name for the component
	// when GraphStatus is "matched", the scaffold record's name otherwise.
	Component string `json:"component"`

	// Kind is the topology block kind. Empty in every non-matched state.
	Kind string `json:"kind,omitempty"`

	// System is the declared system name, when the integration has one.
	System string `json:"system,omitempty"`

	// SystemPath is the system directory the topology record joins on. It
	// travels so a consumer fetching the topology (for the contract registry,
	// which this payload does not embed) can match the right system.
	SystemPath string `json:"systemPath,omitempty"`

	// Contracts the component publishes/subscribes on, resolved against the
	// topology's contracts registry. Absent in every non-matched state.
	Publishes  []ContractEdge `json:"publishes,omitempty"`
	Subscribes []ContractEdge `json:"subscribes,omitempty"`

	// Repository is "owner/repo" from the scaffold record — provenance only.
	// The record can go stale, so identity and contracts come from the graph.
	Repository string `json:"repository,omitempty"`

	// GraphStatus: "matched" | "no-topology" | "not-in-graph" |
	// "topology-error" | "pending".
	GraphStatus string `json:"graphStatus"`

	// TopologyPending is true while the first topology computation is in
	// flight. The header renders from scaffold data; contracts are unknown.
	TopologyPending bool `json:"topologyPending,omitempty"`

	// Checks are graph-derived findings, warns before infos.
	Checks []Check `json:"checks,omitempty"`
}

// ContractEdge is one end of a pub/sub wire a component sits on.
type ContractEdge struct {
	Pubsub string `json:"pubsub"`
	Topic  string `json:"topic"`

	// Contract is the topic's contract shortName when the registry carries it,
	// and the topic's raw contract name otherwise — the same lookup the flow
	// view's detail panel makes.
	Contract string `json:"contract,omitempty"`

	// Publishers and Subscribers are every component the topic declares on each
	// end of the wire, so a contract can be inspected as the connection between
	// components rather than as a name. Absent when the topic declares neither.
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Check is one finding about the integration's place in the system graph.
type Check struct {
	// Severity: "warn" | "info".
	Severity string `json:"severity"`
	Message  string `json:"message"`
}

// catalog serves one integration's catalog entry: header identity and
// contracts from the cached topology report when it has the component, from
// the scaffold record otherwise. It never triggers the topology computation —
// the flow view owns that cost — so a request against a cold cache answers
// promptly with the component pending.
func (s *apiServer) catalog(w http.ResponseWriter, r *http.Request) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		sum := s.summarize(e, systems)
		loaded, entries, errs := s.topologiesLoaded()
		if !loaded {
			// Answer pending now, compute in the background: the pending answer
			// becomes a matched one on the next fetch, without the request
			// queueing behind a dotnet build per host.
			s.warmTopologies()
		}
		return buildCatalogEntry(sum, systems, loaded, entries, errs)
	})
}

// buildCatalogEntry joins the scaffold summary to the cached topology report.
// Separated from the handler so tests exercise the join without HTTP.
func buildCatalogEntry(sum integrationSummary, systems map[string]string, loaded bool, entries []topology.Entry, errs []string) CatalogEntry {
	entry := CatalogEntry{
		Component:  sum.Name,
		System:     sum.System,
		SystemPath: sum.SystemPath,
		Repository: sum.Owner + "/" + sum.Repo,
	}

	// A request against a cold cache answers promptly with scaffold identity
	// rather than queueing behind a dotnet build per host.
	if !loaded {
		entry.GraphStatus = graphPending
		entry.TopologyPending = true
		return entry
	}

	if sum.SystemPath == "" {
		entry.GraphStatus = graphNoTopology
		return entry
	}

	topo, hostErr := findTopology(entries, errs, sum.SystemPath)
	switch {
	case hostErr != "":
		entry.GraphStatus = graphTopologyError
		entry.Checks = appendCheck(entry.Checks, Check{Severity: severityInfo, Message: hostErr})
	case topo == nil:
		entry.GraphStatus = graphNoTopology
	default:
		joinTopology(&entry, sum, topo, systemDeclared(systems, sum))
	}
	return entry
}

// findTopology looks up the cached record for a system path, reporting the
// host's own error message when its graph verb failed. The per-host error
// strings the provider produces are prefixed with the system directory they
// ran in, which is the same identifier space the entry paths use.
func findTopology(entries []topology.Entry, errs []string, systemPath string) (*topology.Entry, string) {
	for i := range entries {
		if entries[i].Path == systemPath {
			return &entries[i], ""
		}
	}
	return nil, hostError(errs, systemPath)
}

func hostError(errs []string, systemPath string) string {
	prefix := systemPath + ": "
	for _, err := range errs {
		if strings.HasPrefix(err, prefix) {
			return err
		}
	}
	return ""
}

// systemDeclared reports whether the integration's system membership comes
// from a sibling system-host scaffold rather than from folder convention. Only
// a declared host justifies a drift warning when the component is absent from
// the graph: a folder-derived "system" is a normal workspace state, not a
// promise that a graph exists.
func systemDeclared(systems map[string]string, sum integrationSummary) bool {
	parent := filepath.Clean(filepath.Dir(sum.ScaffoldEntry.Path))
	_, ok := systems[parent]
	return ok
}

// joinTopology resolves the component against its system's declared graph.
// The join is by directory name: a component's directory is its Name relative
// to the system root.
func joinTopology(entry *CatalogEntry, sum integrationSummary, topo *topology.Entry, declared bool) {
	var comp *topology.Component
	for i := range topo.Components {
		if topo.Components[i].Name == sum.Name {
			comp = &topo.Components[i]
			break
		}
	}
	if comp == nil {
		if !declared {
			// The folder looked like a system but no host declared one, so
			// there is no graph to be absent from — nothing to warn about.
			entry.GraphStatus = graphNoTopology
			return
		}
		entry.GraphStatus = graphNotInGraph
		entry.Checks = appendCheck(entry.Checks, Check{
			Severity: severityWarn,
			Message: fmt.Sprintf("the system graph does not declare a component named %s — renamed without re-scaffolding?", sum.Name),
		})
		return
	}

	entry.GraphStatus = graphMatched
	entry.Component = comp.Name
	entry.Kind = comp.Kind
	for _, p := range comp.Publishes {
		entry.Publishes = append(entry.Publishes, contractEdge(topo, p.PubSub, p.Topic))
	}
	for _, sub := range comp.Subscribes {
		entry.Subscribes = append(entry.Subscribes, contractEdge(topo, sub.PubSub, sub.Topic))
	}
}

// appendCheck keeps the slice severity-ordered: warns before infos.
func appendCheck(checks []Check, c Check) []Check {
	if c.Severity != severityWarn {
		return append(checks, c)
	}
	n := 0
	for n < len(checks) && checks[n].Severity == severityWarn {
		n++
	}
	return append(checks[:n], append([]Check{c}, checks[n:]...)...)
}

// contractEdge resolves one (pubsub, topic) reference against the topology's
// topics and contracts registry: the contract is the registry entry's
// shortName when the topic names a contract and the registry carries it, and
// the raw contract name otherwise — the same lookup the flow view makes. The
// topic's declared publishers and subscribers ride along, so a contract can
// be shown as the connection between components rather than as a name.
func contractEdge(topo *topology.Entry, pubsub, topic string) ContractEdge {
	edge := ContractEdge{Pubsub: pubsub, Topic: topic}
	for _, t := range topo.Topics {
		if t.PubSub != pubsub || t.Topic != topic {
			continue
		}
		edge.Publishers = t.Publishers
		edge.Subscribers = t.Subscribers
		if t.Contract == "" {
			break
		}
		edge.Contract = t.Contract
		for _, c := range topo.Contracts {
			if c.Name == t.Contract && c.ShortName != "" {
				edge.Contract = c.ShortName
				break
			}
		}
		break
	}
	return edge
}

package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
)

// deployProvider reports what one integration has deployed, where.
//
// Like topologyProvider it never fails: a component that cannot be described
// comes back with Error set rather than an error return, because "we could not
// find out" and "it is not deployed" must not render the same. Which of the two
// it was is the command's business to say, not this package's to guess.
type deployProvider func(ctx context.Context, s integrationSummary) deployState

// deployState is one integration's deployment state, or the reason it has none.
type deployState struct {
	// Status is deploy status's own result, passed through unchanged so that the
	// dashboard and the command line cannot come to different conclusions about
	// the same overlays.
	Status *deploy.StatusResult `json:"status,omitempty"`

	// Error is the command's own message, verbatim — an unconfigured GitOps
	// repository, a component name that matches several, a checkout another
	// deploy is holding. Served rather than restated: those messages already
	// name every way to resolve them, and a paraphrase here would be a second
	// thing to keep true.
	//
	// None of them is a statement about the integration. Only the environments
	// inside Status say whether something is deployed.
	Error string `json:"error,omitempty"`

	// Diagnostics is what the command wrote to stderr, one entry per line:
	// which repository it refreshed, and any environment ArgoCD could not be
	// read for. Provenance for what Status shows, not a failure.
	Diagnostics []string `json:"diagnostics,omitempty"`

	// ReadAt is when the command ran, so a reader can tell how current this is.
	ReadAt time.Time `json:"readAt"`
}

// statusCommandProvider is the default provider: it runs the deploy status
// command with a JSON writer and decodes what it prints.
//
// Calling the command rather than reading the GitOps tree here is deliberate.
// Status already owns every refusal that matters — an unset gitopsRepo, an
// ambiguous component, an overlay that pins a tag, an environment nobody has
// onboarded, an unreachable ArgoCD — and each of those is a case where the
// honest answer is subtle and already written down. A second implementation
// would have to get all of them right again.
//
// Domain and System travel with the component name for the same reason
// deploy status takes them as flags: component names are not unique across a
// GitOps tree, and the command refuses an ambiguous one rather than picking.
func statusCommandProvider(version string) deployProvider {
	userAgent := "intropy-cli/" + version
	return func(ctx context.Context, s integrationSummary) deployState {
		var out, logs bytes.Buffer
		err := deploy.Status(ctx, deploy.StatusOptions{
			Component:    s.Name,
			Domain:       s.Domain,
			System:       s.System,
			OutputFormat: deploy.OutputJSON,
			UserAgent:    userAgent,
			Stdout:       &out,
			Stderr:       &logs,
		})

		state := deployState{Diagnostics: diagnosticLines(logs.String()), ReadAt: time.Now()}
		if err != nil {
			state.Error = err.Error()
			return state
		}

		var res deploy.StatusResult
		if err := json.Unmarshal(out.Bytes(), &res); err != nil {
			// The command succeeded but printed something this cannot read —
			// a version skew rather than anything about the deployment.
			state.Error = fmt.Sprintf("read deploy status output: %v", err)
			return state
		}
		state.Status = &res
		return state
	}
}

// diagnosticLines splits captured stderr into entries, dropping blanks. Nil for
// no output, so the field is omitted rather than served as an empty array.
func diagnosticLines(stderr string) []string {
	var out []string
	for line := range strings.SplitSeq(stderr, "\n") {
		if line = strings.TrimSpace(line); line != "" {
			out = append(out, line)
		}
	}
	return out
}

import type { DeployState, EnvironmentStatus, StatusResult } from '../api'
import { Section } from './chrome'
import { CloudIcon } from '../icons'

interface Props {
  state: DeployState | null
  loading: boolean
  refreshing: boolean
  onRefresh: () => void
}

/** The environment ladder: the release and image pins each environment's
 *  overlay declares, plus sync/health when ArgoCD was readable. Everything
 *  comes from `intropy deploy status`; the sentences it computed are rendered
 *  as served and nothing is inferred from absence. */
export function CatalogEnvironments({ state, loading, refreshing, onRefresh }: Props) {
  if (loading && !state) {
    return (
      <Section title="Environments" icon={CloudIcon}>
        <p className="muted">Reading deployment state…</p>
      </Section>
    )
  }
  if (!state) return null

  return (
    <Section title="Environments" icon={CloudIcon}>
      {state.error ? (
        // The command's own message, unedited. It already names every way to
        // resolve the problem, and none of these is evidence about whether the
        // integration is deployed.
        <p className="deploy-error">{state.error}</p>
      ) : state.status ? (
        <Ladder status={state.status} diagnostics={state.diagnostics} />
      ) : (
        <p className="muted">No deployment state.</p>
      )}
      <Provenance state={state} refreshing={refreshing} onRefresh={onRefresh} />
    </Section>
  )
}

function Ladder({
  status,
  diagnostics,
}: {
  status: StatusResult
  diagnostics?: string[]
}) {
  const rows = status.environments ?? []
  const argocdRead = rows.some((e) => e.syncStatus || e.healthStatus)

  return (
    <>
      <Verdict status={status} />

      {!argocdRead && rows.length > 0 && (
        <div className="banner error">
          ArgoCD could not be read, so sync and health are unknown — this says
          nothing about what the overlays pin.
          {diagnostics?.length ? (
            <ul className="deploy-diagnostics">
              {diagnostics.map((d) => (
                <li key={d}>{d}</li>
              ))}
            </ul>
          ) : null}
        </div>
      )}

      {rows.length === 0 ? (
        <p className="muted">This component declares no environments.</p>
      ) : (
        <table className="deploy-table">
          <thead>
            <tr>
              <th>Environment</th>
              <th>Version</th>
              <th>Image</th>
              {argocdRead && <th>Sync</th>}
              <th>Age</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((env, i) => (
              <Row key={env.environment} env={env} argocdRead={argocdRead} relation={relationToLast(rows, i)} />
            ))}
          </tbody>
        </table>
      )}

      {status.notes?.length ? (
        <ul className="deploy-notes">
          {status.notes.map((note) => (
            <li key={note}>{note}</li>
          ))}
        </ul>
      ) : null}
    </>
  )
}

/** The one-line answer under which the table sits, rendered only when there
 *  is one: agreement across every environment is the claim the command exists
 *  to make and is worth a sentence. A disagreement is positional — the
 *  markers on the rows already say which environment runs newer bits, and a
 *  sentence here would repeat them. */
function Verdict({ status }: { status: StatusResult }) {
  if (!status.consistent) return null
  return <p className="deploy-verdict agrees">{status.summary}</p>
}

/** Whether an environment runs the same bits as the furthest-downstream one:
 *  'same', 'ahead', 'behind', 'differs', or undefined when either side pins
 *  no digest (nothing to compare, never a disagreement claim). 'ahead' and
 *  'behind' are stated only when both sides carry a SemVer release to order
 *  by; a digest difference with no version to rank it is 'differs'. The
 *  furthest-downstream environment itself is always 'same'. */
function relationToLast(rows: EnvironmentStatus[], index: number): 'same' | 'ahead' | 'behind' | 'differs' | undefined {
  const self = rows[index]
  const last = [...rows].reverse().find((r) => r.onboarded && pinSignature(r))
  if (!last || last === self || !self.onboarded) return undefined
  const mine = pinSignature(self)
  if (!mine) return undefined
  if (mine === pinSignature(last)) return 'same'

  const mineV = self.release ? parseRelease(self.release) : undefined
  const lastV = last.release ? parseRelease(last.release) : undefined
  if (mineV && lastV) {
    const cmp = compareRelease(mineV, lastV)
    if (cmp < 0) return 'behind'
    if (cmp > 0) return 'ahead'
  }
  return 'differs'
}

// [major, minor, patch, prerelease]. A release without a prerelease sorts
// after every prerelease of the same core — SemVer ordering.
type ParsedRelease = [number, number, number, string]

function parseRelease(v: string): ParsedRelease | undefined {
  const m = /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/.exec(v)
  if (!m) return undefined
  return [Number(m[1]), Number(m[2]), Number(m[3]), m[4] ?? '']
}

function compareRelease(a: ParsedRelease, b: ParsedRelease): number {
  for (let i = 0; i < 3; i++) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1
  }
  if (a[3] === b[3]) return 0
  if (a[3] === '') return 1
  if (b[3] === '') return -1
  return a[3] < b[3] ? -1 : 1
}

/** pinSignature is an environment's digests in declared order, or undefined
 *  when any pin is missing — there is then no set of bits to compare. */
function pinSignature(env: EnvironmentStatus): string | undefined {
  const pins = env.pins ?? []
  if (pins.length === 0) return undefined
  const digests: string[] = []
  for (const p of pins) {
    if (!p.digest) return undefined
    digests.push(p.digest)
  }
  return digests.join(' ')
}

function Row({
  env,
  argocdRead,
  relation,
}: {
  env: EnvironmentStatus
  argocdRead: boolean
  relation?: 'same' | 'ahead' | 'behind' | 'differs'
}) {
  const span = argocdRead ? 4 : 3

  return (
    <tr className={env.onboarded ? undefined : 'not-onboarded'}>
      <th>
        {env.environment}
        {relation && relation !== 'same' && (
          <span
            className={`deploy-drift ${relation}`}
            title={
              relation === 'ahead'
                ? 'runs a newer release than the furthest-downstream environment — an unpromoted change'
                : relation === 'behind'
                  ? 'runs an older release than the furthest-downstream environment'
                  : 'runs different bits than the furthest-downstream environment'
            }
          >
            {relation === 'ahead' ? '↑ ahead' : relation === 'behind' ? '↓ behind' : '≠ differs'}
          </span>
        )}
        {env.syncPolicy === 'manual' && <span className="deploy-tag">manual</span>}
        {env.pending && <span className="deploy-tag waiting">waiting</span>}
      </th>
      {env.onboarded ? (
        <>
          <td>{releaseCell(env)}</td>
          <td>
            <Pins env={env} />
          </td>
          {argocdRead && (
            <td>
              {env.syncStatus || NONE}
              {env.healthStatus ? ` · ${env.healthStatus}` : ''}
            </td>
          )}
          <td>{ageCell(env)}</td>
        </>
      ) : (
        // Never omit the row: an environment the component declares but that
        // cannot be read is the fact an operator most needs to see.
        <td className="muted" colSpan={span}>
          {env.reason || 'no readable overlay here'}
        </td>
      )}
    </tr>
  )
}

/** Every declared image, not just the first. Digest pins shorten the same way
 *  the command shortens them; tag pins get the `:tag` treatment that signals
 *  drift risk. */
function Pins({ env }: { env: EnvironmentStatus }) {
  const pins = env.pins ?? []
  if (pins.length === 0) return <>{NONE}</>

  return (
    <ul className="deploy-pins">
      {pins.map((pin) => (
        <li key={pin.image}>
          <span className="deploy-image">{shortImage(pin.image)}</span>
          {pin.digest ? (
            <span title={pin.digest}>{shortDigest(pin.digest)}</span>
          ) : pin.tag ? (
            <span className="deploy-unpinned" title={`pinned to the tag ${pin.tag}, not a digest`}>
              :{pin.tag}
            </span>
          ) : (
            <span className="muted">{NONE}</span>
          )}
        </li>
      ))}
    </ul>
  )
}

function Provenance({ state, refreshing, onRefresh }: Omit<Props, 'loading'>) {
  return (
    <div className="deploy-foot">
      <div className="deploy-foot-text">
        {state?.readAt && <span className="muted">read {readAge(state.readAt)}</span>}
      </div>
      <button
        type="button"
        className="flow-refresh"
        onClick={onRefresh}
        disabled={refreshing}
        title="Re-run deploy status for this integration"
      >
        {refreshing ? 'Refreshing…' : 'Refresh'}
      </button>
    </div>
  )
}

/** What the terminal prints in an empty cell. */
const NONE = '—'

/** releaseCell mirrors the command: an environment deployed from a commit has
 *  no release but still has something true to say, and the `@` prefix is what
 *  keeps the commit from being misread as a version. */
function releaseCell(env: EnvironmentStatus): string {
  if (env.release) return env.release
  if (env.sourceCommit) return `@${env.sourceCommit.slice(0, 7)}`
  return NONE
}

function ageCell(env: EnvironmentStatus): string {
  return env.deployedAt ? humanAge(Date.now() - Date.parse(env.deployedAt)) : NONE
}

function readAge(readAt: string): string {
  const ms = Date.now() - Date.parse(readAt)
  return Number.isNaN(ms) ? 'just now' : `${humanAge(ms)} ago`
}

/** humanAge mirrors the command at one unit, truncating rather than rounding:
 *  119 minutes is "1h", never "2h". */
function humanAge(ms: number): string {
  const minutes = Math.floor(ms / 60_000)
  if (minutes < 1) return '<1m'
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 48) return `${hours}h`
  return `${Math.floor(hours / 24)}d`
}

/** shortDigest mirrors the command character for character, so a digest read
 *  here is the same string deploy and promote print. */
function shortDigest(digest: string): string {
  const prefix = 'sha256:'
  const hex = digest.startsWith(prefix) ? digest.slice(prefix.length) : null
  return hex && hex.length > 12 ? prefix + hex.slice(0, 12) : digest
}

/** shortImage drops the registry host so the column reads as a component
 *  name, keeping the last two path segments. */
function shortImage(image: string): string {
  const parts = image.split('/')
  return parts.length <= 2 ? image : parts.slice(-2).join('/')
}

